$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json;$rel='foundation/advancement/AllAdvancements.java';$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$rel";$x=[IO.File]::ReadAllText($p);$start=$x.IndexOf("`n`n`tpublic static final CreateAdvancement FROGPORT");$end=$x.LastIndexOf("`n}");if($start-lt 0-or$end-lt$start){throw 'Logistics advancement tail missing'};$old=$x.Substring($start,$end-$start);$rx=[regex]'(?ms)\s*public static final CreateAdvancement (?<n>FROGPORT|PACKAGER|FACTORY_GAUGE|STOCK_TICKER|TABLE_CLOTH_SHOP) = create\(.*?\);';$blocks=@{};foreach($match in $rx.Matches($old)){$blocks[$match.Groups['n'].Value]=$match.Value.TrimStart()};if($blocks.Count-ne5){throw 'Expected five logistics advancement blocks'};$nl=if($x.Contains("`r`n")){"`r`n"}else{"`n"};$cardboard="public static final CreateAdvancement CARDBOARD = create(`"cardboard`", b -> b.icon(AllItems.CARDBOARD)${nl}`t`t.title(`"Part and Parcel`")${nl}`t`t.description(`"Produce or obtain your first Cardboard`")${nl}`t`t.whenIconCollected()${nl}`t`t.after(MIXER));";$new="${nl}${nl}`t"+(@($cardboard,$blocks.PACKAGER,$blocks.STOCK_TICKER,$blocks.FROGPORT,$blocks.TABLE_CLOTH_SHOP,$blocks.FACTORY_GAUGE)-join"${nl}${nl}`t");$updated=$x.Substring(0,$start)+$new+$x.Substring($end);[IO.File]::WriteAllText($p,$updated,[Text.UTF8Encoding]::new($false));$c=[pscustomobject]@{from=$old;to=$new};$e=$m.files|Where-Object path -eq $rel;$e.changes=@($e.changes)+$c;$e.status='Official Create 6 logistics advancements retained in dependency-safe declaration order, including native Cardboard prerequisite.';$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Reordered native logistics advancements.'
